<?php
define('ML_APP',true);define('ML_ROOT',__DIR__.'/..');require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/RateLimit.php';if(php_sapi_name()!=='cli'){http_response_code(404);exit('Not Found');}$started=microtime(true);$log=array('action'=>'rate_prune','version'=>ML_APP_VERSION,'started_at'=>date('Y-m-d H:i:s'));try{$log['rate_deleted']=\Core\RateLimit::prune(86400);}catch(\Throwable $e){$log['rate_error']=$e->getMessage();}try{$dir=ML_ROOT.'/cache';if(is_dir($dir)){$now=time();$deleted=0;foreach(glob($dir.'/*.cache')as $f){if($now-@filemtime($f)>86400*30){if(@unlink($f)){$deleted++;}}}$log['cache_deleted']=$deleted;}}catch(\Throwable $e){$log['cache_error']=$e->getMessage();}try{$pdo=\Core\DB::pdo();$st=$pdo->query("SELECT PARTITION_NAME FROM information_schema.PARTITIONS
